/**
 * The curated demo catalog.
 *
 * Written as data rather than generated by a model, for two reasons: a demo has
 * to behave the same way twice, and the scenarios below only work if the prices
 * and stock are chosen deliberately. The merchants still carry the voice notes
 * they would have sent, so deleting catalog.json rebuilds all of this through
 * the real Stage-1 extraction — the cache is a convenience, not a substitute.
 *
 * Every price, floor and stock count is set so that a specific demo lands:
 *   A negotiation   chocolate cake under ₹500 → 3 bakeries, one rejected
 *   B cross-sell    birthday cake under ₹700 → cupcakes + candles fit
 *   C upsell        cake for 8 under ₹800 → premium at ₹620, not the ₹760
 *   D dead stock    blueberry muffin, 24 in stock, weak movement
 *   E no deal       The Oven Room's floor sits above a ₹500 ceiling
 */
import { writeFileSync } from "node:fs";

const now = "2026-09-01T09:00:00Z";
const M = [];
const items = [];
const policies = [];

function merchant(m) { M.push(m); return m; }
function product(mid, id, name, category, price, stock, opts = {}) {
  items.push({
    item_id: id, merchant_id: mid, name, category,
    attributes: opts.attributes ?? {},
    price: { value: price, currency: "INR", confidence: 1 },
    stock: { quantity: stock, confidence: 1 },
    source: { type: "merchant_entry", raw_text: opts.raw ?? name },
    needs_merchant_confirmation: false,
    extracted_at: now,
    ...(opts.extra ?? {}),
  });
  if (opts.floor !== undefined) {
    policies.push({ item_id: id, list_price: price, floor_price: opts.floor, max_rounds: 3, set_by: "merchant", set_at: now });
  }
  return id;
}

