// ── Held items ─────────────────────────────────────────────────────────────
//
// Two products the shopkeeper described without settling. They are the whole
// clarification story: the system asks rather than guessing, and an AI buyer
// cannot transact on them until the merchant answers. A catalog where every
// row is already confirmed has nothing to demonstrate and — as the audit
// caught — nothing to test either.
items.push({
  item_id: "itm_hazel_011", merchant_id: "mer_hazel",
  name: "Fresh Fruit Pastry", category: "food.snack",
  attributes: { flavour: "seasonal fruit" },
  price: { value: 0, currency: "INR", confidence: 0.1 },
  stock: { quantity: 6, confidence: 0.9 },
  source: { type: "voice_note", raw_text: "fruit tart bhi hai, price abhi decide nahi kiya, roz badalta hai" },
  needs_merchant_confirmation: true,
  extracted_at: now,
  tags: ["dessert", "tart", "tea snack"], cost_price: 95,
});
